insert into units (id,course_id,level,position,title,icon,topics) values
  ('u1','en-for-pt',1,1,'Saudações, Cortesia e Respeito','🤝','Cumprimentos formais, apresentações respeitosas, títulos de tratamento, verbo to be no presente.'),
  ('u2','en-for-pt',1,2,'O Lar e a Família','🏡','Grau de parentesco, cômodos da casa, refeições em família, agradecimento à mesa.'),
  ('u3','en-for-pt',1,3,'Trabalho, Mérito e Vocação','⚙️','Profissões, números, horas, rotina produtiva, negócios básicos.'),
  ('u4','en-for-pt',1,4,'Pátria, Ordem e Dever Cívico','🏛️','Direções, lugares da cidade, instituições, símbolos nacionais, deveres cívicos.'),
  ('u5','en-for-pt',1,5,'Tradição, Fé e Sabedoria','✝️','Dias da semana (ênfase no domingo em família), virtudes cardeais, provérbios em inglês.'),
  ('u6','en-for-pt',1,6,'A Nova Geração e o Futuro','🌱','Cores, animais, natureza, atividades ao ar livre, obediência aos pais, rotina escolar saudável.'),
  ('u7','en-for-pt',2,7,'Caráter e Convivência','🧱','Passado simples, futuro com will / going to, comparativos; virtudes: honestidade e poupança.'),
  ('u8','en-for-pt',3,8,'Empreendedorismo, História e Cidadania','📈','Present Perfect, condicionais (1º e 2º), modais de dever e conselho (must, should, ought to).'),
  ('u9','en-for-pt',4,9,'Retórica, Tradição e Liderança','⚖️','Voz passiva, discurso indireto, terceiro condicional, argumentação sobre liberdade e ordem.'),
  ('u10','en-for-pt',5,10,'Maestria Clássica e Diplomacia','🎖️','Inversões enfáticas, subjuntivo formal, expressões idiomáticas cultas e retórica persuasiva.');
