  ('u9l2:v:earned','u9l2',5,'earned','ganhamos'),
  ('u9l2:v:season','u9l2',6,'season','temporada'),
  ('u10l1:v:rarely does','u10l1',1,'rarely does','raramente'),
  ('u10l1:v:not only … but also','u10l1',2,'not only … but also','não apenas … mas também'),
  ('u10l1:v:never have I','u10l1',3,'never have I','nunca eu'),
  ('u10l1:v:seldom','u10l1',4,'seldom','raramente (formal)'),
  ('u10l1:v:moving','u10l1',5,'moving','comovente'),
  ('u10l1:v:worth defending','u10l1',6,'worth defending','digno de ser defendido'),
  ('u10l2:v:I propose that','u10l2',1,'I propose that','eu proponho que'),
  ('u10l2:v:be held','u10l2',2,'be held','seja realizada'),
  ('u10l2:v:essential','u10l2',3,'essential','essencial'),
  ('u10l2:v:be heard','u10l2',4,'be heard','seja ouvida'),
  ('u10l2:v:put the cart before the horse','u10l2',5,'put the cart before the horse','colocar a carroça na frente dos bois'),
  ('u10l2:v:proceed','u10l2',6,'proceed','prosseguir');
insert into dialogue_lines (id,lesson_id,position,character_id,en,pt) values
  ('u1l1:d:0','u1l1',1,'alice','Good morning, Sir.','Bom dia, senhor.'),
  ('u1l1:d:1','u1l1',2,'ayrton','Good morning, Ma''am. You are on time.','Bom dia, senhora. A senhora está pontual.'),
  ('u1l1:d:2','u1l1',3,'alice','Punctuality is a form of respect.','A pontualidade é uma forma de respeito.'),
  ('u1l1:d:3','u1l1',4,'ayrton','Indeed. Good afternoon, and goodbye.','De fato. Boa tarde e adeus.'),
  ('u1l2:d:0','u1l2',1,'ayrton','My name is Ayrton. I am an engineer.','Meu nome é Ayrton. Sou engenheiro.'),
  ('u1l2:d:1','u1l2',2,'alice','Nice to meet you, Mister Ayrton. I am Alice.','Prazer em conhecê-lo, senhor Ayrton. Sou Alice.'),
  ('u1l2:d:2','u1l2',3,'ayrton','Welcome to our meeting, Doctor Alice.','Bem-vinda à nossa reunião, doutora Alice.'),
  ('u1l2:d:3','u1l2',4,'alice','Thank you. The pleasure is mine.','Obrigada. O prazer é meu.'),
  ('u1l3:d:0','u1l3',1,'alice','I am a lawyer. You are an engineer.','Sou advogada. Você é engenheiro.'),
  ('u1l3:d:1','u1l3',2,'ayrton','Yes. He is a soldier, and she is a teacher.','Sim. Ele é soldado e ela é professora.'),
  ('u1l3:d:2','u1l3',3,'alice','We are neighbors and they are our friends.','Somos vizinhos e eles são nossos amigos.'),
  ('u1l3:d:3','u1l3',4,'ayrton','We are ready to begin.','Estamos prontos para começar.'),
  ('u1l4:d:0','u1l4',1,'ayrton','Excuse me, Ma''am. Please sit here.','Com licença, senhora. Por favor, sente-se aqui.'),
  ('u1l4:d:1','u1l4',2,'alice','Thank you very much, Sir.','Muito obrigada, senhor.'),
  ('u1l4:d:2','u1l4',3,'ayrton','You are welcome. I am sorry for the delay.','De nada. Sinto muito pelo atraso.'),
  ('u1l4:d:3','u1l4',4,'alice','No problem. I will help you with pleasure.','Sem problema. Eu o ajudarei com prazer.'),
  ('u2l1:d:0','u2l1',1,'maria','This is my husband, Gabriel.','Este é meu marido, Gabriel.'),
  ('u2l1:d:1','u2l1',2,'gabriel','And this is my wife, Maria.','E esta é minha esposa, Maria.'),
  ('u2l1:d:2','u2l1',3,'davi','I am your son, Davi. I love my mother and my father.','Sou seu filho, Davi. Amo minha mãe e meu pai.'),
  ('u2l1:d:3','u2l1',4,'liz','I am your daughter, Liz.','Sou sua filha, Liz.'),
  ('u2l2:d:0','u2l2',1,'maria','Welcome to our home. This is the living room.','Bem-vindos ao nosso lar. Esta é a sala de estar.'),
  ('u2l2:d:1','u2l2',2,'davi','Mom, where is Dad?','Mãe, onde está o papai?'),
  ('u2l2:d:2','u2l2',3,'maria','He is in the kitchen. He is cooking.','Ele está na cozinha. Está cozinhando.'),
  ('u2l2:d:3','u2l2',4,'liz','I am in the garden with the flowers.','Estou no jardim com as flores.'),
  ('u2l3:d:0','u2l3',1,'gabriel','Dinner is ready. Please come to the table.','O jantar está pronto. Venham à mesa, por favor.'),
  ('u2l3:d:1','u2l3',2,'davi','I want soup and bread, please.','Quero sopa e pão, por favor.'),
  ('u2l3:d:2','u2l3',3,'liz','I want water, Dad.','Quero água, papai.'),
  ('u2l3:d:3','u2l3',4,'maria','We eat dinner together every night.','Jantamos juntos toda noite.'),
  ('u2l4:d:0','u2l4',1,'gabriel','Let us give thanks. Lord, bless this food.','Vamos dar graças. Senhor, abençoe este alimento.'),
  ('u2l4:d:1','u2l4',2,'liz','Amen.','Amém.'),
  ('u2l4:d:2','u2l4',3,'davi','Pass the bread, please. This soup is delicious.','Passe o pão, por favor. Esta sopa está deliciosa.'),
  ('u2l4:d:3','u2l4',4,'maria','Thank you, my dear. Would you like more?','Obrigada, querido. Você quer mais?'),
  ('u3l1:d:0','u3l1',1,'jose','I am the founder of this company.','Sou o fundador desta empresa.'),
  ('u3l1:d:1','u3l1',2,'flavia','I am the manager of a farm. My husband is an engineer.','Sou a gestora de uma fazenda. Meu marido é engenheiro.'),
  ('u3l1:d:2','u3l1',3,'jose','My wife is an architect. Work is a blessing.','Minha esposa é arquiteta. O trabalho é uma bênção.'),
  ('u3l1:d:3','u3l1',4,'flavia','Good work builds a good country.','O bom trabalho constrói um bom país.'),
  ('u3l2:d:0','u3l2',1,'jose','What time is it?','Que horas são?'),
  ('u3l2:d:1','u3l2',2,'flavia','It is eight o''clock.','São oito horas em ponto.'),
  ('u3l2:d:2','u3l2',3,'jose','The meeting is at nine. We have one hour.','A reunião é às nove. Temos uma hora.'),
  ('u3l2:d:3','u3l2',4,'flavia','Ten people will come. We will be ready.','Dez pessoas virão. Estaremos prontos.'),
  ('u3l3:d:0','u3l3',1,'flavia','I wake up early every day.','Eu acordo cedo todos os dias.'),
  ('u3l3:d:1','u3l3',2,'jose','I work hard, and I rest on Sunday.','Eu trabalho duro e descanso no domingo.'),
  ('u3l3:d:2','u3l3',3,'flavia','Never be late. Time is a gift.','Nunca se atrase. O tempo é um presente.'),
  ('u3l3:d:3','u3l3',4,'jose','A good routine is the road to success.','Uma boa rotina é o caminho para o sucesso.'),
  ('u3l4:d:0','u3l4',1,'jose','Honesty is the base of every good business.','A honestidade é a base de todo bom negócio.'),
  ('u3l4:d:1','u3l4',2,'flavia','We have an agreement. Please sign the contract.','Temos um acordo. Por favor, assine o contrato.'),
  ('u3l4:d:2','u3l4',3,'jose','Profit comes from hard work.','O lucro vem do trabalho duro.'),
  ('u3l4:d:3','u3l4',4,'flavia','And private property must be respected.','E a propriedade privada deve ser respeitada.'),
  ('u4l1:d:0','u4l1',1,'ayrton','Excuse me, Captain. Where is the city hall?','Com licença, capitão. Onde fica a prefeitura?'),
  ('u4l1:d:1','u4l1',2,'lucas','Go straight ahead. Turn left at the corner.','Siga em frente. Vire à esquerda na esquina.'),
  ('u4l1:d:2','u4l1',3,'ayrton','Is it far from here?','Fica longe daqui?'),
  ('u4l1:d:3','u4l1',4,'lucas','No, it is near. It is on your right.','Não, é perto. Fica à sua direita.'),
  ('u4l2:d:0','u4l2',1,'lucas','This is a peaceful city. The church is near the school.','Esta é uma cidade pacífica. A igreja fica perto da escola.'),
  ('u4l2:d:1','u4l2',2,'ayrton','I am building a new hospital next to the park.','Estou construindo um novo hospital ao lado do parque.'),
  ('u4l2:d:2','u4l2',3,'lucas','The bank and the courthouse are on the same street.','O banco e o fórum ficam na mesma rua.'),
  ('u4l2:d:3','u4l2',4,'ayrton','A good city needs order.','Uma boa cidade precisa de ordem.'),
  ('u4l3:d:0','u4l3',1,'lucas','I am a soldier. I serve my country.','Sou soldado. Sirvo meu país.'),
  ('u4l3:d:1','u4l3',2,'ayrton','I am a citizen. I respect our flag.','Sou cidadão. Respeito nossa bandeira.'),
  ('u4l3:d:2','u4l3',3,'lucas','We stand for the anthem with respect.','Ficamos de pé com respeito durante o hino.'),
  ('u4l3:d:3','u4l3',4,'ayrton','We love our homeland.','Amamos nossa pátria.'),
  ('u4l4:d:0','u4l4',1,'lucas','Duty comes before comfort.','O dever vem antes do conforto.'),
  ('u4l4:d:1','u4l4',2,'ayrton','We obey the law, and we vote with responsibility.','Obedecemos à lei e votamos com responsabilidade.'),
  ('u4l4:d:2','u4l4',3,'lucas','Order protects our freedom.','A ordem protege nossa liberdade.'),
  ('u4l4:d:3','u4l4',4,'ayrton','Free men serve their country with honor.','Homens livres servem seu país com honra.'),
  ('u5l1:d:0','u5l1',1,'beto','Children, what day is today?','Crianças, que dia é hoje?'),
  ('u5l1:d:1','u5l1',2,'gael','Today is Sunday, Dad!','Hoje é domingo, papai!'),
  ('u5l1:d:2','u5l1',3,'beto','Correct. Monday comes after Sunday, and Friday comes before Saturday.','Correto. A segunda vem depois do domingo, e a sexta vem antes do sábado.'),
  ('u5l1:d:3','u5l1',4,'laura','I like Sunday the most.','Eu gosto mais do domingo.'),
  ('u5l2:d:0','u5l2',1,'clara','On Sunday, we go to church together.','No domingo, vamos juntos à igreja.'),
  ('u5l2:d:1','u5l2',2,'gael','We pray, and we read the Bible.','Nós oramos e lemos a Bíblia.'),
  ('u5l2:d:2','u5l2',3,'beto','Then we visit the grandparents. It is a family tradition.','Depois visitamos os avós. É uma tradição de família.'),
  ('u5l2:d:3','u5l2',4,'laura','Family is a blessing.','A família é uma bênção.'),
  ('u5l3:d:0','u5l3',1,'beto','A virtue is a good habit. There are four cardinal virtues.','Uma virtude é um bom hábito. Há quatro virtudes cardeais.'),
  ('u5l3:d:1','u5l3',2,'clara','They are prudence, justice, fortitude and temperance.','São prudência, justiça, fortaleza e temperança.'),
  ('u5l3:d:2','u5l3',3,'gael','Prudence means thinking before acting.','Prudência significa pensar antes de agir.'),
  ('u5l3:d:3','u5l3',4,'beto','And faith gives us strength.','E a fé nos dá força.'),
  ('u5l4:d:0','u5l4',1,'beto','A proverb is a short sentence full of wisdom.','Um provérbio é uma frase curta cheia de sabedoria.'),
  ('u5l4:d:1','u5l4',2,'clara','Honor your father and your mother.','Honra teu pai e tua mãe.'),
  ('u5l4:d:2','u5l4',3,'gael','A soft answer turns away anger.','A resposta branda desvia o furor.'),
  ('u5l4:d:3','u5l4',4,'beto','Be humble, be diligent and be patient.','Seja humilde, diligente e paciente.'),
  ('u6l1:d:0','u6l1',1,'miguel','The flag is green and yellow, and it has a blue circle.','A bandeira é verde e amarela, e tem um círculo azul.'),
  ('u6l1:d:1','u6l1',2,'heloisa','My dress is white.','Meu vestido é branco.'),
  ('u6l1:d:2','u6l1',3,'arthur','My shoes are black. My ball is red.','Meus sapatos são pretos. Minha bola é vermelha.'),
  ('u6l1:d:3','u6l1',4,'cecilia','I like all the colors.','Eu gosto de todas as cores.'),
  ('u6l2:d:0','u6l2',1,'noah','There is a horse and a cow on the farm.','Há um cavalo e uma vaca na fazenda.'),
  ('u6l2:d:1','u6l2',2,'antonella','I see a little bird.','Eu vejo um passarinho.'),
  ('u6l2:d:2','u6l2',3,'theo','Look! The eagle is flying high.','Olhem! A águia está voando alto.'),
  ('u6l2:d:3','u6l2',4,'maite','Doggy! My dog is nice.','Cachorrinho! Meu cachorro é legal.'),
  ('u6l3:d:0','u6l3',1,'davi','The sun is bright. Let us play outside.','O sol está forte. Vamos brincar lá fora.'),
  ('u6l3:d:1','u6l3',2,'liz','I see a big tree near the river.','Eu vejo uma árvore grande perto do rio.'),
  ('u6l3:d:2','u6l3',3,'miguel','We can climb the mountain with Dad.','Podemos subir a montanha com o papai.'),
  ('u6l3:d:3','u6l3',4,'heloisa','Look at the rain. God makes the flowers grow.','Olhe a chuva. Deus faz as flores crescerem.'),
  ('u6l4:d:0','u6l4',1,'arthur','Dad says: obey your parents and listen to your teacher.','O papai diz: obedeça seus pais e ouça sua professora.'),
  ('u6l4:d:1','u6l4',2,'noah','Mom, may I play now?','Mamãe, posso brincar agora?'),
  ('u6l4:d:2','u6l4',3,'flavia','First, finish your homework, Noah.','Primeiro, termine sua lição de casa, Noah.'),
  ('u6l4:d:3','u6l4',4,'noah','Yes, Mom. I will obey.','Sim, mamãe. Eu vou obedecer.'),
  ('u7l1:d:0','u7l1',1,'miguel','Dad, yesterday I found a wallet at school.','Pai, ontem eu achei uma carteira na escola.'),
  ('u7l1:d:1','u7l1',2,'ayrton','What did you do with it?','O que você fez com ela?'),
  ('u7l1:d:2','u7l1',3,'miguel','I gave it to the teacher. It was not mine.','Eu a entreguei à professora. Não era minha.'),
  ('u7l1:d:3','u7l1',4,'ayrton','Honesty is the best path, my son. I am proud of you.','A honestidade é o melhor caminho, meu filho. Tenho orgulho de você.'),
  ('u7l2:d:0','u7l2',1,'arthur','Dad, I am going to save my money.','Pai, eu vou poupar o meu dinheiro.'),
  ('u7l2:d:1','u7l2',2,'jose','Good. What will you buy?','Bom. O que você vai comprar?'),
  ('u7l2:d:2','u7l2',3,'arthur','I will buy a gift for Mom. Saving is better than spending.','Vou comprar um presente para a mamãe. Poupar é melhor que gastar.'),
  ('u7l2:d:3','u7l2',4,'jose','Smart choice. Small savings will become a big reward.','Escolha inteligente. Pequenas economias se tornarão uma grande recompensa.'),
  ('u8l1:d:0','u8l1',1,'flavia','We have built this company with honest work.','Nós construímos esta empresa com trabalho honesto.'),
  ('u8l1:d:1','u8l1',2,'jose','Yes. We have never broken a contract.','Sim. Nunca quebramos um contrato.'),
  ('u8l1:d:2','u8l1',3,'flavia','If we keep our word, customers will trust us.','Se cumprirmos a palavra, os clientes confiarão em nós.'),
  ('u8l1:d:3','u8l1',4,'jose','We must serve them well. That is true leadership.','Devemos servi-los bem. Isso é liderança de verdade.'),
  ('u8l2:d:0','u8l2',1,'gael','Dad, why should I study history?','Pai, por que eu deveria estudar história?'),
  ('u8l2:d:1','u8l2',2,'beto','If you study history, you will understand your country.','Se você estudar história, você entenderá o seu país.'),
  ('u8l2:d:2','u8l2',3,'gael','Have you read many old books?','O senhor já leu muitos livros antigos?'),
  ('u8l2:d:3','u8l2',4,'beto','I have read hundreds. You ought to start with one good book.','Li centenas. Convém começar com um bom livro.'),
  ('u9l1:d:0','u9l1',1,'alice','Our freedoms were protected by brave citizens.','Nossas liberdades foram protegidas por cidadãos corajosos.'),
  ('u9l1:d:1','u9l1',2,'lucas','And they must be defended by every generation.','E devem ser defendidas por cada geração.'),
  ('u9l1:d:2','u9l1',3,'alice','The law is obeyed here, and justice is served.','A lei é obedecida aqui, e a justiça é feita.'),
  ('u9l1:d:3','u9l1',4,'lucas','Order and liberty are not enemies. They are partners.','Ordem e liberdade não são inimigas. São parceiras.'),
  ('u9l2:d:0','u9l2',1,'flavia','Rafael told me the harvest would be larger this year.','Rafael me disse que a safra seria maior este ano.'),
  ('u9l2:d:1','u9l2',2,'rafael','I said that because the rain came on time.','Eu disse isso porque a chuva veio na hora certa.'),
  ('u9l2:d:2','u9l2',3,'flavia','If we had planted earlier, we would have earned even more.','Se tivéssemos plantado mais cedo, teríamos ganhado ainda mais.'),
  ('u9l2:d:3','u9l2',4,'rafael','Perhaps. Next season, we will plan better.','Talvez. Na próxima temporada, planejaremos melhor.'),
  ('u10l1:d:0','u10l1',1,'beto','Rarely does a nation produce such courage.','Raramente uma nação produz tanta coragem.'),
  ('u10l1:d:1','u10l1',2,'alice','Not only did they fight bravely, but they also governed wisely.','Eles não apenas lutaram com bravura, mas também governaram com sabedoria.'),
  ('u10l1:d:2','u10l1',3,'beto','Never have I read a speech so moving.','Nunca li um discurso tão comovente.'),
  ('u10l1:d:3','u10l1',4,'alice','Seldom is truth easy, yet it is always worth defending.','Raramente a verdade é fácil, mas ela sempre vale ser defendida.'),
  ('u10l2:d:0','u10l2',1,'jose','I propose that the meeting be held on Monday.','Proponho que a reunião seja realizada na segunda-feira.'),
  ('u10l2:d:1','u10l2',2,'ayrton','It is essential that every party be heard.','É essencial que cada parte seja ouvida.'),
  ('u10l2:d:2','u10l2',3,'jose','Let us not put the cart before the horse. First, the facts.','Não coloquemos a carroça na frente dos bois. Primeiro, os fatos.'),
  ('u10l2:d:3','u10l2',4,'ayrton','Wisely said. We will proceed with prudence.','Bem dito. Prosseguiremos com prudência.');
insert into chronicles (id,title,icon,intro,unlock_after_unit) values
  ('c1','O Relógio de Bolso de Ayrton','⌚','Ayrton ensina ao filho Miguel o valor da pontualidade e da palavra empenhada.','u2'),
  ('c2','O Jantar de Domingo na Casa de Maria Fulana','🍲','Maria Fulana e Gabriel preparam uma recepção calorosa para os vizinhos.','u4'),
  ('c3','O Primeiro Contrato de José','📜','José explica a Arthur e Cecília como funciona a criação de valor, o lucro honesto e o cumprimento de acordos.','u6'),
  ('c4','A Lição de História do Professor Beto','🏛️','Beto leva Gael e Laura a um museu e narra o heroísmo de quem defendeu a pátria.','u8');
insert into chronicle_cast (chronicle_id,character_id) values
  ('c1','ayrton'),
  ('c1','miguel'),
