insert into chronicle_segments (id,chronicle_id,position,lines,stop_kind,stop_question,stop_options,stop_answer,stop_why) values
  ('c1:1','c1',1,'[{"who":"ayrton","en":"Miguel, look at my pocket watch. It was my father''s.","pt":"Miguel, olhe o meu relógio de bolso. Era do meu pai."},{"who":"miguel","en":"It is beautiful, Dad. Why do you carry it?","pt":"É lindo, pai. Por que o senhor o leva consigo?"},{"who":"ayrton","en":"Because time is a gift. We must not waste it.","pt":"Porque o tempo é um presente. Não devemos desperdiçá-lo."}]'::jsonb,'deduce','O que Ayrton quer ensinar com o relógio?','["Time is a gift","Gold is everything","Watches are old"]'::jsonb,'Time is a gift','O relógio lembra que o tempo é um dom a ser bem usado.'),
  ('c1:2','c1',2,'[{"who":"ayrton","en":"We have a visit at three o''clock. It is an important visit.","pt":"Temos uma visita às três horas. É uma visita importante."},{"who":"miguel","en":"But Dad, my friends want me to play now.","pt":"Mas, pai, meus amigos querem que eu brinque agora."},{"who":"ayrton","en":"I gave my word to Mister Silva. A man keeps his word.","pt":"Dei a minha palavra ao senhor Silva. Um homem cumpre a sua palavra."}]'::jsonb,'moral','O que Miguel deve fazer?','["Go with Dad and keep the promise","Stay and play with friends","Tell a lie to avoid the visit"]'::jsonb,'Go with Dad and keep the promise','Cumprir a palavra empenhada vale mais do que a diversão do momento.'),
  ('c1:3','c1',3,'[{"who":"ayrton","en":"It is two thirty. We must leave now.","pt":"São duas e meia. Precisamos sair agora."},{"who":"miguel","en":"Dad, the car is not starting!","pt":"Pai, o carro não está pegando!"},{"who":"ayrton","en":"Stay calm. We will walk fast, and I will call Mister Silva.","pt":"Calma. Vamos andar depressa, e eu ligarei para o senhor Silva."}]'::jsonb,'deduce','O que Ayrton fará para honrar o compromisso?','["Walk fast and warn Mister Silva","Cancel the visit","Wait for the car all day"]'::jsonb,'Walk fast and warn Mister Silva','Quem leva o compromisso a sério busca uma solução e avisa a outra parte.'),
  ('c1:4','c1',4,'[{"who":"ayrton","en":"Mister Silva, we are here. Thank you for waiting.","pt":"Senhor Silva, chegamos. Obrigado por esperar."},{"who":"miguel","en":"Dad, now I understand. Punctuality is respect.","pt":"Pai, agora eu entendo. Pontualidade é respeito."}]'::jsonb,'complete','Complete a fala de Miguel: “Punctuality is ____.”','["respect","luck","hurry"]'::jsonb,'respect','Pontualidade é uma forma de respeito pelo tempo dos outros.'),
  ('c2:1','c2',1,'[{"who":"maria","en":"Gabriel, the neighbors will arrive at six. Is the roast ready?","pt":"Gabriel, os vizinhos chegam às seis. O assado está pronto?"},{"who":"gabriel","en":"Almost. Davi, please set the table.","pt":"Quase. Davi, por favor, arrume a mesa."},{"who":"davi","en":"Yes, Dad. How many plates do we need?","pt":"Sim, pai. Quantos pratos precisamos?"},{"who":"maria","en":"Four for us and two for our guests.","pt":"Quatro para nós e dois para os nossos convidados."}]'::jsonb,'complete','Complete: “We need six plates: four for us and ____ for our guests.”','["two","ten","one"]'::jsonb,'two','Quatro da família mais dois convidados somam seis pratos.'),
  ('c2:2','c2',2,'[{"who":"maria","en":"Welcome, neighbors! Please come in.","pt":"Bem-vindos, vizinhos! Entrem, por favor."},{"who":"davi","en":"Mom, Mrs. Santos looks tired.","pt":"Mãe, a dona Santos parece cansada."},{"who":"gabriel","en":"Make yourselves at home. Dinner is ready.","pt":"Fiquem à vontade. O jantar está pronto."}]'::jsonb,'moral','Qual é a melhor atitude de Maria?','["Offer her a chair and a glass of water","Ignore it and keep cooking","Ask her to leave early"]'::jsonb,'Offer her a chair and a glass of water','Hospitalidade é perceber a necessidade do hóspede e servi-lo.'),
  ('c2:3','c2',3,'[{"who":"gabriel","en":"Let us give thanks for this food and for good neighbors.","pt":"Vamos agradecer por esta comida e por bons vizinhos."},{"who":"liz","en":"Can I say the prayer, Dad?","pt":"Posso fazer a oração, pai?"},{"who":"gabriel","en":"Of course, Liz.","pt":"Claro, Liz."}]'::jsonb,'deduce','O que acontece a seguir?','["Liz says a short prayer of thanks","Everyone starts eating at once","Liz leaves the table"]'::jsonb,'Liz says a short prayer of thanks','Gabriel acabou de permitir; a oração de gratidão vem antes da refeição.'),
  ('c2:4','c2',4,'[{"who":"davi","en":"Mom, may I have more soup, please?","pt":"Mãe, posso tomar mais sopa, por favor?"},{"who":"maria","en":"Yes, Davi. Good manners make a meal sweeter.","pt":"Sim, Davi. Boas maneiras tornam a refeição mais doce."}]'::jsonb,'complete','Complete: “May I have more soup, ____?”','["please","now","fast"]'::jsonb,'please','“Please” é a palavra de cortesia ao pedir algo.'),
  ('c3:1','c3',1,'[{"who":"jose","en":"Arthur, Cecília, today I will sign a contract.","pt":"Arthur, Cecília, hoje vou assinar um contrato."},{"who":"arthur","en":"What is a contract, Dad?","pt":"O que é um contrato, pai?"},{"who":"jose","en":"It is a promise written on paper.","pt":"É uma promessa escrita no papel."}]'::jsonb,'deduce','O que é um contrato para José?','["A promise written on paper","A game","A gift"]'::jsonb,'A promise written on paper','Um contrato registra uma palavra dada que deve ser cumprida.'),
  ('c3:2','c3',2,'[{"who":"cecilia","en":"Dad, will you earn money?","pt":"Pai, o senhor vai ganhar dinheiro?"},{"who":"jose","en":"Yes, honest profit. We create value, and customers pay for it.","pt":"Sim, lucro honesto. Criamos valor, e os clientes pagam por ele."},{"who":"arthur","en":"Is profit bad, Dad?","pt":"Lucro é ruim, pai?"}]'::jsonb,'moral','Como José responde?','["No. Honest profit rewards good work","Yes. Profit is always wrong","Profit is only luck"]'::jsonb,'No. Honest profit rewards good work','O lucro honesto é o prêmio de quem serve bem e cria valor.'),
  ('c3:3','c3',3,'[{"who":"jose","en":"The customer wants a lower price, but my cost is higher.","pt":"O cliente quer um preço menor, mas o meu custo é maior."},{"who":"arthur","en":"Can we change the contract and cheat him?","pt":"Podemos mudar o contrato e enganá-lo?"}]'::jsonb,'moral','O que José diz?','["No. A deal is a deal, and we keep our word","Yes, if he does not notice","Yes, if we need money"]'::jsonb,'No. A deal is a deal, and we keep our word','Honestidade não depende de ser descoberto: acordo é acordo.'),
  ('c3:4','c3',4,'[{"who":"jose","en":"We delivered on time. The customer paid and thanked us.","pt":"Entregamos no prazo. O cliente pagou e nos agradeceu."},{"who":"cecilia","en":"Dad, I want to build a business too!","pt":"Pai, eu também quero construir um negócio!"}]'::jsonb,'complete','Complete: “Hard work ____ off.”','["pays","stops","falls"]'::jsonb,'pays','“Hard work pays off” significa que o trabalho duro compensa.'),
  ('c4:1','c4',1,'[{"who":"beto","en":"Gael, Laura, welcome to the museum. Look at this old flag.","pt":"Gael, Laura, bem-vindos ao museu. Olhem esta bandeira antiga."},{"who":"gael","en":"Dad, who carried this flag?","pt":"Pai, quem carregou esta bandeira?"},{"who":"beto","en":"A brave soldier. He defended his country.","pt":"Um soldado corajoso. Ele defendeu o seu país."}]'::jsonb,'deduce','O que Beto vai contar?','["A story of a soldier who defended his country","A story about a cartoon","A story about shopping"]'::jsonb,'A story of a soldier who defended his country','Beto já disse que o soldado defendeu o país: é essa a história.'),
  ('c4:2','c4',2,'[{"who":"beto","en":"The soldier was hurt, but he did not leave his post.","pt":"O soldado estava ferido, mas não abandonou o seu posto."},{"who":"laura","en":"Daddy, was he afraid?","pt":"Papai, ele teve medo?"},{"who":"beto","en":"Yes, but courage is acting rightly even when we are afraid.","pt":"Sim, mas coragem é agir corretamente mesmo quando temos medo."}]'::jsonb,'moral','O que é coragem, segundo Beto?','["Acting rightly even when afraid","Never feeling fear","Showing off to others"]'::jsonb,'Acting rightly even when afraid','Coragem não é ausência de medo, é fazer o certo apesar dele.'),
  ('c4:3','c4',3,'[{"who":"gael","en":"What did the soldier do after the war?","pt":"O que o soldado fez depois da guerra?"},{"who":"beto","en":"He went home, worked hard, and raised his family.","pt":"Voltou para casa, trabalhou duro e criou a sua família."}]'::jsonb,'deduce','Como foi a vida do soldado depois da guerra?','["He returned home and worked honestly","He became rich by deceit","He left his family"]'::jsonb,'He returned home and worked honestly','O herói também é o homem que volta e sustenta a família com trabalho honesto.'),
  ('c4:4','c4',4,'[{"who":"laura","en":"I want to be brave like him.","pt":"Eu quero ser corajosa como ele."},{"who":"beto","en":"Brave and kind, my little one. History teaches us who we are.","pt":"Corajosa e bondosa, minha pequena. A história nos ensina quem somos."}]'::jsonb,'complete','Complete: “History teaches us who we ____.”','["are","is","was"]'::jsonb,'are','“Who we are”: o verbo concorda com “we”.');
insert into listening_stations (unit_id,title,lines,questions,roleplay) values
  ('u1','A Reunião','[{"who":"ayrton","en":"Good morning, Doctor Alice. Welcome to our meeting.","pt":"Bom dia, doutora Alice. Bem-vinda à nossa reunião."},{"who":"alice","en":"Good morning, Mister Ayrton. Thank you, Sir.","pt":"Bom dia, senhor Ayrton. Obrigada, senhor."},{"who":"ayrton","en":"Our meeting starts at nine o''clock. You are on time.","pt":"Nossa reunião começa às nove horas. A senhora está pontual."},{"who":"alice","en":"Punctuality is respect, Sir. I always arrive early.","pt":"Pontualidade é respeito, senhor. Eu sempre chego cedo."},{"who":"ayrton","en":"Excellent. Please, sit down.","pt":"Excelente. Por favor, sente-se."},{"who":"alice","en":"Thank you. The pleasure is mine.","pt":"Obrigada. O prazer é meu."}]'::jsonb,'[{"q":"A que horas começa a reunião?","options":["At eight","At nine","At ten"],"answer":"At nine"},{"q":"Como Alice descreve a pontualidade?","options":["As respect","As luck","As luxury"],"answer":"As respect"},{"q":"Quando Alice costuma chegar?","options":["Early","Late","Never"],"answer":"Early"}]'::jsonb,'{"who":"ayrton","ask":"What time does our meeting start?","askPt":"A que horas começa a nossa reunião?","model":"Our meeting starts at nine o''clock.","modelPt":"Nossa reunião começa às nove horas.","accept":["Our meeting starts at nine o''clock.","The meeting starts at nine o''clock."]}'::jsonb),
  ('u2','O Jantar','[{"who":"maria","en":"Welcome to our home, neighbors. Dinner is ready.","pt":"Bem-vindos à nossa casa, vizinhos. O jantar está pronto."},{"who":"gabriel","en":"Please sit at the table. We have soup and fresh bread.","pt":"Por favor, sentem-se à mesa. Temos sopa e pão fresco."},{"who":"davi","en":"Mom, I set the table. I put five plates.","pt":"Mãe, eu arrumei a mesa. Coloquei cinco pratos."},{"who":"maria","en":"Thank you, Davi. Liz, please bring the water.","pt":"Obrigada, Davi. Liz, por favor, traga a água."},{"who":"liz","en":"Yes, Mom. Here is the water.","pt":"Sim, mãe. Aqui está a água."},{"who":"gabriel","en":"Let us give thanks before we eat.","pt":"Vamos agradecer antes de comer."}]'::jsonb,'[{"q":"O que há para o jantar?","options":["Soup and bread","Pizza and juice","Fish and rice"],"answer":"Soup and bread"},{"q":"Quantos pratos Davi colocou?","options":["Four","Five","Six"],"answer":"Five"},{"q":"O que fazem antes de comer?","options":["Give thanks","Watch TV","Wash the car"],"answer":"Give thanks"}]'::jsonb,'{"who":"maria","ask":"Would you like some soup?","askPt":"O senhor aceita um pouco de sopa?","model":"Yes, please. Thank you very much.","modelPt":"Sim, por favor. Muito obrigado.","accept":["Yes, please. Thank you very much.","Yes, please. Thank you."]}'::jsonb),
  ('u3','A Fábrica','[{"who":"jose","en":"Flavia, we open at seven o''clock every day.","pt":"Flavia, abrimos às sete horas todos os dias."},{"who":"flavia","en":"I know. My team arrives at six thirty.","pt":"Eu sei. Minha equipe chega às seis e meia."},{"who":"jose","en":"Good. Hard work builds a good company.","pt":"Bom. Trabalho duro constrói uma boa empresa."},{"who":"flavia","en":"We have twelve workers and three trucks.","pt":"Temos doze funcionários e três caminhões."},{"who":"jose","en":"Honest work deserves a fair salary.","pt":"Trabalho honesto merece um salário justo."},{"who":"flavia","en":"I agree. Payday is on Friday.","pt":"Concordo. O pagamento é na sexta-feira."}]'::jsonb,'[{"q":"A que horas a fábrica abre?","options":["At seven","At six","At nine"],"answer":"At seven"},{"q":"Quantos funcionários há?","options":["Ten","Twelve","Three"],"answer":"Twelve"},{"q":"Qual é o dia do pagamento?","options":["Monday","Friday","Sunday"],"answer":"Friday"}]'::jsonb,'{"who":"jose","ask":"What time do you start work?","askPt":"A que horas você começa a trabalhar?","model":"I start work at seven o''clock.","modelPt":"Eu começo a trabalhar às sete horas.","accept":["I start work at seven o''clock.","I start work at seven."]}'::jsonb),
  ('u4','A Praça','[{"who":"lucas","en":"Excuse me, Sir. Where is the city hall?","pt":"Com licença, senhor. Onde fica a prefeitura?"},{"who":"ayrton","en":"Go straight and turn left at the flag.","pt":"Siga em frente e vire à esquerda na bandeira."},{"who":"lucas","en":"Thank you. Is the library near?","pt":"Obrigado. A biblioteca é perto?"},{"who":"ayrton","en":"Yes, it is next to the church.","pt":"Sim, fica ao lado da igreja."},{"who":"lucas","en":"I serve my country, and I respect the law.","pt":"Eu sirvo ao meu país e respeito a lei."},{"who":"ayrton","en":"That is an honorable duty, Sir.","pt":"Esse é um dever honroso, senhor."}]'::jsonb,'[{"q":"Onde virar à esquerda?","options":["At the flag","At the bank","At the school"],"answer":"At the flag"},{"q":"Onde fica a biblioteca?","options":["Next to the church","Behind the bank","Near the river"],"answer":"Next to the church"},{"q":"O que Lucas faz?","options":["He serves his country","He sells cars","He teaches piano"],"answer":"He serves his country"}]'::jsonb,'{"who":"lucas","ask":"Where is the library?","askPt":"Onde fica a biblioteca?","model":"The library is next to the church.","modelPt":"A biblioteca fica ao lado da igreja.","accept":["The library is next to the church.","It is next to the church."]}'::jsonb),
  ('u5','O Domingo','[{"who":"beto","en":"Today is Sunday. We go to church as a family.","pt":"Hoje é domingo. Vamos à igreja em família."},{"who":"clara","en":"Gael, put on your good shoes.","pt":"Gael, calce os seus sapatos bons."},{"who":"gael","en":"Yes, Mom. Dad, will you tell a story after lunch?","pt":"Sim, mãe. Pai, você vai contar uma história depois do almoço?"},{"who":"beto","en":"Yes. A story about an honest king.","pt":"Sim. Uma história sobre um rei honesto."},{"who":"laura","en":"I like stories, Daddy.","pt":"Eu gosto de histórias, papai."},{"who":"clara","en":"After the story, we will thank God for our family.","pt":"Depois da história, agradeceremos a Deus pela nossa família."}]'::jsonb,'[{"q":"Que dia é hoje?","options":["Sunday","Monday","Friday"],"answer":"Sunday"},{"q":"Sobre o que será a história?","options":["An honest king","A funny dog","A long trip"],"answer":"An honest king"},{"q":"O que farão depois da história?","options":["Thank God","Play soccer","Go shopping"],"answer":"Thank God"}]'::jsonb,'{"who":"beto","ask":"What do you do on Sunday?","askPt":"O que você faz no domingo?","model":"On Sunday, we go to church with our family.","modelPt":"No domingo, vamos à igreja com a nossa família.","accept":["On Sunday, we go to church with our family.","On Sunday I go to church with my family."]}'::jsonb),
  ('u6','A Brincadeira','[{"who":"theo","en":"Miguel, the dog is brown and the cat is white.","pt":"Miguel, o cachorro é marrom e o gato é branco."},{"who":"miguel","en":"Yes. We must be kind to animals.","pt":"Sim. Devemos ser gentis com os animais."},{"who":"cecilia","en":"Look at the green trees! Nature is beautiful.","pt":"Olhem as árvores verdes! A natureza é linda."},{"who":"noah","en":"Mom said we should obey and come home at six.","pt":"A mamãe disse que devemos obedecer e voltar para casa às seis."},{"who":"antonella","en":"Okay, Noah. I obey Mom and Dad.","pt":"Está bem, Noah. Eu obedeço à mamãe e ao papai."},{"who":"arthur","en":"Obedience makes a family happy.","pt":"A obediência faz uma família feliz."}]'::jsonb,'[{"q":"Qual é a cor do cachorro?","options":["Brown","White","Green"],"answer":"Brown"},{"q":"A que horas devem voltar?","options":["At six","At nine","At noon"],"answer":"At six"},{"q":"O que faz uma família feliz?","options":["Obedience","Money","Television"],"answer":"Obedience"}]'::jsonb,'{"who":"theo","ask":"What color is the dog?","askPt":"De que cor é o cachorro?","model":"The dog is brown.","modelPt":"O cachorro é marrom.","accept":["The dog is brown.","It is brown."]}'::jsonb),
  ('u7','Ontem e Amanhã','[{"who":"ayrton","en":"Yesterday, Miguel returned a lost wallet.","pt":"Ontem, Miguel devolveu uma carteira perdida."},{"who":"jose","en":"Honest boy! Arthur saved ten dollars last month.","pt":"Menino honesto! Arthur poupou dez dólares no mês passado."},{"who":"arthur","en":"Yes. I will buy a gift for Mom tomorrow.","pt":"Sim. Vou comprar um presente para a mamãe amanhã."},{"who":"miguel","en":"Saving is better than spending, Dad.","pt":"Poupar é melhor que gastar, pai."},{"who":"ayrton","en":"True. Small savings will become a big reward.","pt":"Verdade. Pequenas economias se tornarão uma grande recompensa."},{"who":"jose","en":"Boys, I am proud of both of you.","pt":"Meninos, tenho orgulho de vocês dois."}]'::jsonb,'[{"q":"O que Miguel devolveu?","options":["A wallet","A book","A watch"],"answer":"A wallet"},{"q":"Quanto Arthur poupou?","options":["Ten dollars","Two dollars","A hundred dollars"],"answer":"Ten dollars"},{"q":"Para quem será o presente?","options":["For Mom","For Dad","For the teacher"],"answer":"For Mom"}]'::jsonb,'{"who":"ayrton","ask":"What did you do yesterday?","askPt":"O que você fez ontem?","model":"Yesterday I found a wallet and returned it.","modelPt":"Ontem achei uma carteira e a devolvi.","accept":["Yesterday I found a wallet and returned it.","Yesterday I returned a wallet."]}'::jsonb),
  ('u8','Contrato e História','[{"who":"flavia","en":"We have signed the contract with our new customer.","pt":"Assinamos o contrato com o nosso novo cliente."},{"who":"jose","en":"Excellent. If we deliver on time, they will order again.","pt":"Excelente. Se entregarmos no prazo, eles pedirão de novo."},{"who":"beto","en":"Gael, have you finished your reading?","pt":"Gael, você terminou a sua leitura?"},{"who":"gael","en":"Yes, Dad. I have read two chapters.","pt":"Sim, pai. Li dois capítulos."},{"who":"beto","en":"Good. You should read a little every day.","pt":"Bom. Você deveria ler um pouco todos os dias."},{"who":"jose","en":"The same is true for business. Small steps, every day.","pt":"O mesmo vale para os negócios. Pequenos passos, todos os dias."}]'::jsonb,'[{"q":"Com quem assinaram o contrato?","options":["A new customer","A bank","A school"],"answer":"A new customer"},{"q":"Quantos capítulos Gael leu?","options":["Two","Ten","One"],"answer":"Two"},{"q":"Qual é o conselho de Beto?","options":["Read a little every day","Play every day","Sleep late"],"answer":"Read a little every day"}]'::jsonb,'{"who":"beto","ask":"Have you finished your reading?","askPt":"Você terminou a sua leitura?","model":"Yes, I have finished my reading.","modelPt":"Sim, terminei a minha leitura.","accept":["Yes, I have finished my reading.","Yes, I have finished it."]}'::jsonb),
  ('u9','Liberdade e Safra','[{"who":"alice","en":"Our liberties were won by courageous citizens.","pt":"Nossas liberdades foram conquistadas por cidadãos corajosos."},{"who":"lucas","en":"And they must be defended by every generation.","pt":"E devem ser defendidas por cada geração."},{"who":"flavia","en":"Rafael said the harvest would be larger this year.","pt":"Rafael disse que a safra seria maior este ano."},{"who":"rafael","en":"It will be, because the rain came on time.","pt":"Será, porque a chuva veio na hora certa."},{"who":"flavia","en":"If we had planted earlier, we would have earned more.","pt":"Se tivéssemos plantado mais cedo, teríamos ganhado mais."},{"who":"alice","en":"Wisdom is learning from experience, not from regret.","pt":"Sabedoria é aprender com a experiência, não com o arrependimento."}]'::jsonb,'[{"q":"Quem conquistou as liberdades?","options":["Courageous citizens","Foreign kings","Nobody"],"answer":"Courageous citizens"},{"q":"Por que a safra será maior?","options":["The rain came on time","They bought a truck","It is Sunday"],"answer":"The rain came on time"},{"q":"O que Flavia diz sobre plantar mais cedo?","options":["They would have earned more","They would have lost","Nothing would change"],"answer":"They would have earned more"}]'::jsonb,'{"who":"alice","ask":"What must every generation do?","askPt":"O que cada geração deve fazer?","model":"Every generation must defend freedom.","modelPt":"Cada geração deve defender a liberdade.","accept":["Every generation must defend freedom.","Every generation must defend our freedom."]}'::jsonb),
  ('u10','Oratória','[{"who":"beto","en":"Rarely does a nation produce such courage.","pt":"Raramente uma nação produz tanta coragem."},{"who":"alice","en":"Not only did they fight bravely, but they also governed wisely.","pt":"Eles não apenas lutaram com bravura, mas também governaram com sabedoria."},{"who":"jose","en":"I propose that the next meeting be held on Monday.","pt":"Proponho que a próxima reunião seja realizada na segunda-feira."},{"who":"ayrton","en":"It is essential that every party be heard.","pt":"É essencial que cada parte seja ouvida."},{"who":"beto","en":"Let us not put the cart before the horse.","pt":"Não coloquemos a carroça na frente dos bois."},{"who":"alice","en":"Wisely said. First the facts, then the decision.","pt":"Bem dito. Primeiro os fatos, depois a decisão."}]'::jsonb,'[{"q":"Quando será a próxima reunião?","options":["On Monday","On Friday","On Sunday"],"answer":"On Monday"},{"q":"O que é essencial, segundo Ayrton?","options":["Every party be heard","Everyone agree","Nobody speak"],"answer":"Every party be heard"},{"q":"Qual expressão Beto usa?","options":["Put the cart before the horse","Break the ice","Hit the road"],"answer":"Put the cart before the horse"}]'::jsonb,'{"who":"jose","ask":"When shall we hold the meeting?","askPt":"Quando devemos realizar a reunião?","model":"I suggest that we hold it on Monday.","modelPt":"Sugiro que a realizemos na segunda-feira.","accept":["I suggest that we hold it on Monday.","I propose that we hold it on Monday."]}'::jsonb);
insert into pronunciation_tips (id,title,words,pattern,tip_pt) values
  ('th_voiceless','Som de TH (sem voz)','["think","three","truth","thank","thanks","thing","both","path","month","faith"]'::jsonb,'^th|th$','Para o TH de “truth”, coloque a ponta da língua levemente entre os dentes e sopre, sem som de F ou T.'),
  ('th_voiced','Som de TH (com voz)','["the","this","that","these","they","them","mother","father","with","brother","other"]'::jsonb,'th','Língua entre os dentes, como no TH anterior, mas faça a garganta vibrar. Não troque por D nem Z.'),
  ('final_consonant','Consoante final seca','["work","walk","book","word","good","help","night","great","start","meet","at"]'::jsonb,'[kdtpb]$','Não adicione um “i” no final de “work”. Corte o som no K, no D ou no T, sem soltar vogal.'),
  ('s_cluster','S + consoante no início','["school","street","student","state","speak","special","story","study","sport"]'::jsonb,'^s[ptkcm]|^str|^spl|^scr','Não coloque um “e” antes do S: diga “skool”, não “iskool”. Comece direto no S.'),
  ('h_aspirated','Som de H aspirado','["house","home","have","his","her","hello","how","help","husband","happy","history"]'::jsonb,'^h','O H em inglês é um sopro suave, como se você embaçasse um vidro. Não é o “rr” do português.'),
  ('r_sound','O R americano','["right","work","red","free","great","correct","are","for","very","morning","truth","grow"]'::jsonb,'r','Enrole a língua para trás sem encostar no céu da boca e sem vibrar. Não use o “rr” nem o “h” do português.'),
  ('ed_ending','Final -ed','["worked","asked","needed","wanted","stopped","helped","planted","earned","returned"]'::jsonb,'ed$','O -ed tem três sons: /t/ depois de som surdo (worked), /d/ depois de som sonoro (earned) e /id/ depois de T ou D (wanted).'),
  ('short_i','I curto e I longo','["ship","sheep","live","leave","fill","feel","it","this","in","is"]'::jsonb,'^i|^sh','“Ship” tem som curto e relaxado; “sheep” é longo e tenso. Não alongue o I curto como se fosse “i” do português.'),
  ('schwa','Vogal fraca (schwa)','["about","family","again","today","banana","the","a","of","to"]'::jsonb,'^a|^o','Vogais sem acento viram um “ã” bem curto e relaxado: “a-BOUT”, “FAM-ly”. Acente só a sílaba forte.'),
  ('w_sound','Som de W','["we","work","would","water","well","will","welcome","what","with","one","away"]'::jsonb,'^w','Arredonde os lábios como para assoprar uma vela, depois abra. É um “u” curto, sem o V do português.'),
  ('j_dg','Som de J e DG','["job","judge","just","jump","large","age","knowledge","engineer"]'::jsonb,'^j|dg|ge$','Comece com língua no céu da boca, como “dj”: “djob”, não “jóbi”. Lábios levemente projetados.'),
  ('tion','Final -tion','["nation","information","education","question","tradition","station"]'::jsonb,'tion$','Pronuncie “shun”: na-SHUN, não “ta-ção”. A sílaba forte vem antes do -tion.'),
  ('silent','Letras mudas','["Wednesday","listen","honest","hour","honor","half","know","knowledge","building"]'::jsonb,'^kn|^wr|^hon|^hour','Algumas letras não soam: “honest” começa com O, “listen” não tem T, “know” não tem K.'),
  ('final_l','L final','["all","well","tell","real","family","will","people","little","help"]'::jsonb,'l$','Encoste a ponta da língua atrás dos dentes de cima e segure. Não transforme em “u” como no português (“Brasiu”).'),
  ('final_nasal','M e N finais','["from","time","them","come","name","men","in","on","an","can"]'::jsonb,'[mn]$','Feche bem os lábios no M final e encoste a língua no N final. Não nasalize a vogal anterior como em “tão”.'),
  ('z_between','S entre vogais','["is","easy","has","as","was","these","please","busy","those","music"]'::jsonb,'s$|^e?asy','O S de “is”, “easy” e “has” soa como Z. No fim de palavras como “is” e “was”, vibre a garganta.');
insert into wisdom_quotes (id,kind,en,pt,source) values
  ('w01','bible','A good name is to be chosen rather than great riches.','Mais vale o bom nome do que grandes riquezas.','Provérbios 22:1'),
  ('w02','bible','A soft answer turns away wrath.','A resposta branda desvia o furor.','Provérbios 15:1'),
  ('w03','bible','A slack hand causes poverty, but the hand of the diligent makes rich.','A mão negligente empobrece, mas a mão diligente enriquece.','Provérbios 10:4'),
  ('w04','bible','Honor your father and your mother.','Honra teu pai e tua mãe.','Êxodo 20:12'),
  ('w05','bible','The fear of the Lord is the beginning of knowledge.','O temor do Senhor é o princípio do conhecimento.','Provérbios 1:7'),
  ('w06','bible','Train up a child in the way he should go.','Instrui a criança no caminho em que deve andar.','Provérbios 22:6'),
  ('w07','bible','Trust in the Lord with all your heart.','Confia no Senhor de todo o teu coração.','Provérbios 3:5'),
  ('w08','bible','Righteousness exalts a nation.','A justiça engrandece uma nação.','Provérbios 14:34'),
  ('w09','bible','Iron sharpens iron, and one man sharpens another.','O ferro com o ferro se afia, e um homem afia o outro.','Provérbios 27:17'),
  ('w10','bible','Go to the ant, O sluggard; consider her ways, and be wise.','Vai ter com a formiga, preguiçoso; observa seus caminhos e sê sábio.','Provérbios 6:6'),
  ('w11','bible','The Lord is my shepherd; I shall not want.','O Senhor é o meu pastor; nada me faltará.','Salmo 23:1'),
  ('w12','bible','Pride goes before destruction, and a haughty spirit before a fall.','A soberba precede a ruína, e o espírito altivo precede a queda.','Provérbios 16:18'),
  ('w13','bible','Commit your work to the Lord, and your plans will be established.','Confia ao Senhor as tuas obras, e teus planos se firmarão.','Provérbios 16:3'),
  ('w14','classic','Courage is not simply one of the virtues, but the form of every virtue at the testing point.','A coragem não é apenas uma das virtudes, mas a forma de toda virtude no momento da prova.','C. S. Lewis, The Screwtape Letters'),
  ('w15','classic','The Christian ideal has not been tried and found wanting. It has been found difficult and left untried.','O ideal cristão não foi tentado e achado insuficiente. Foi achado difícil e deixado sem tentativa.','G. K. Chesterton, What''s Wrong with the World'),
  ('w16','classic','Tradition means giving a vote to the most obscure of all classes, our ancestors.','Tradição significa dar voto à mais obscura de todas as classes: nossos antepassados.','G. K. Chesterton, Orthodoxy'),
  ('w17','classic','Society is a partnership between those who are living, those who are dead, and those who are to be born.','A sociedade é uma parceria entre os que vivem, os que morreram e os que ainda hão de nascer.','Edmund Burke, Reflections on the Revolution in France'),
  ('w18','classic','Do not waste time bothering whether you love your neighbor; act as if you did.','Não perca tempo se perguntando se ama o seu próximo; aja como se amasse.','C. S. Lewis, Mere Christianity');
insert into readings (id,title,author,level,cost_talents,words,source_note) values
  ('r1','Salmo 23 (trecho)','King James Version',1,0,'[["The Lord","O Senhor"],["is","é"],["my","meu"],["shepherd","pastor"],["I shall not want","nada me faltará"],["He makes me","Ele me faz"],["lie down","deitar"],["in green pastures","em verdes pastos"],["He leads me","Ele me conduz"],["beside","ao lado de"],["still waters","águas tranquilas"]]'::jsonb,'Salmo 23:1-2, em inglês americano atual.'),
  ('r2','A Formiga Diligente','Provérbios 6 e fábula clássica (adaptação)',1,20,'[["In summer,","No verão,"],["the ant","a formiga"],["works","trabalha"],["every day.","todos os dias."],["She","Ela"],["gathers","recolhe"],["food","comida"],["for the winter.","para o inverno."],["The grasshopper","O gafanhoto"],["only","apenas"],["sings","canta"],["and plays.","e brinca."],["When winter comes,","Quando o inverno chega,"],["the ant","a formiga"],["has bread,","tem pão,"],["but he has none.","mas ele não tem nenhum."]]'::jsonb,'Adaptação didática de fábula de Esopo; ver Provérbios 6:6-8.'),
  ('r3','O Peregrino (abertura)','John Bunyan, The Pilgrim''s Progress',2,40,'[["As I walked","Enquanto eu caminhava"],["through the wilderness","pelo deserto"],["of this world,","deste mundo,"],["I lighted on","deparei-me com"],["a certain place","um certo lugar"],["where was a den,","onde havia uma cova,"],["and I laid me down","e me deitei"],["in that place","naquele lugar"],["to sleep;","para dormir;"],["and, as I slept,","e, enquanto dormia,"],["I dreamed a dream.","tive um sonho."]]'::jsonb,'Domínio público (1678). Texto original, grafia modernizada.');
